#include "fur_guide_worker_pool_candidate.h"
#include "fur_root_distribution_candidate.h"
#include <chrono>
#include <iostream>
int main(){try{std::vector<GeometryDeformedVertexCandidate>surface(3);surface[0].position={0,0,0};surface[1].position={4,0,0};surface[2].position={0,4,0};for(auto&v:surface)v.normal={0,0,1};auto anchors=distributeFurRootsCandidate(surface,{{0,1,2}},100000,2,123);auto serial=sampleFurSurfaceGuidesCandidate(anchors,surface);FurGuideWorkerPoolCandidate one(1),four(4);for(auto*pool:{&one,&four}){auto output=pool->sample(anchors,surface);for(size_t i=0;i<serial.size();++i)if(serial[i].root!=output[i].root||serial[i].tip!=output[i].tip)throw std::runtime_error("fur worker output mismatch");auto bad=anchors;bad[50000].vertices[0]=3;bool rejected=false;try{pool->sample(bad,surface);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("worker invalid input accepted");auto retry=pool->sample(anchors,surface);if(retry.back().tip!=serial.back().tip)throw std::runtime_error("worker recovery failed");}
 auto benchmark=[&](auto sample){auto start=std::chrono::steady_clock::now();for(unsigned i=0;i<20;++i){auto output=sample();if(output.size()!=anchors.size())throw std::runtime_error("benchmark output");}return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/20;};double serialMs=benchmark([&]{return sampleFurSurfaceGuidesCandidate(anchors,surface);}),parallelMs=benchmark([&]{return four.sample(anchors,surface);});std::cout<<"fur_guide_workers_count=100000 workers_1_4_exact=true error_recovery=true serial_mean_ms="<<serialMs<<" workers4_mean_ms="<<parallelMs<<" scope=component_benchmark\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
